                if seen[a][b] or I[a][b]!=col: continue
                seen[a][b]=True; cells.append((a,b))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+dr,b+dc
                    if 0<=x<H and 0<=y<W: stack.append((x,y))
            comps.append(cells)
    return comps,bg

def f(I):
    comps,bg=components(I)
    O=[row[:] for row in I]
    H,W=len(I),len(I[0])
    def box(cells):
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        R1,R2=min(rs)-1,max(rs)+1; C1,C2=min(cs)-1,max(cs)+1
        return max(R1,0),min(R2,H-1),max(C1,0),min(C2,W-1)
    for comp in comps:
        if len(comp)<2: continue
        R1,R2,C1,C2=box(comp)
        for r in [R1,R2]:
            for c in range(C1,C2+1):
                if O[r][c]==bg: O[r][c]=3
        for c in [C1,C2]:
            for r in range(R1,R2+1):
                if O[r][c]==bg: O[r][c]=3
    return O

